#!/usr/bin/env python3
"""Generate port/src/missions_data.c from the mission table in PART2.EXE
(27 records of 0x50 bytes at 0x5656c). Run: gen_missions.py build/part2.bin out.c"""
import struct, sys

IMAGE_BASE, TABLE, COUNT, SIZE = 0x10000, 0x5656c, 27, 0x50

img = open(sys.argv[1], 'rb').read()
rows = []
for m in range(COUNT):
    r = struct.unpack_from('<20i', img, TABLE - IMAGE_BASE + m * SIZE)
    rows.append('    { ' + ', '.join(str(v) for v in r) + ' },')
open(sys.argv[2], 'w').write(
    '/* Generated by re/tools/gen_missions.py from PART2.EXE 0x5656c - do not edit. */\n'
    '#include "missions.h"\n\n'
    'const MissionDef g_missions[MISSION_COUNT] = {\n' + '\n'.join(rows) + '\n};\n')
